import Foundation

struct OpenCodeRequestContext: Equatable {
    static let clientName = "desktop"
    static let userAgent = "opencode/1.19.4"

    var sessionID: String
    var parentSessionID: String?
    var projectID: String?
    var requestID: String?

    init(sessionID: String, parentSessionID: String? = nil, projectID: String? = nil, requestID: String? = nil) {
        self.sessionID = sessionID
        self.parentSessionID = parentSessionID
        self.projectID = projectID
        self.requestID = requestID
    }

    static func generated() -> OpenCodeRequestContext {
        OpenCodeRequestContext(sessionID: Self.sessionID(from: UUID().uuidString))
    }

    static func sessionID(from rawID: String) -> String {
        let normalized = rawID
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "-", with: "")
            .lowercased()
        guard !normalized.isEmpty else { return "ses_" + UUID().uuidString.replacingOccurrences(of: "-", with: "").lowercased() }
        if normalized.hasPrefix("ses_") { return normalized }
        return "ses_" + normalized
    }

    var affinity: String {
        if let parentSessionID, !parentSessionID.isEmpty { return parentSessionID }
        return sessionID
    }

    var headers: [String: String] {
        var headers: [String: String] = [
            "x-opencode-session-id": sessionID,
            "x-session-affinity": affinity,
            "X-Session-Id": affinity,
            "x-opencode-session": affinity,
            "x-opencode-client": Self.clientName,
            "User-Agent": Self.userAgent
        ]
        if let projectID, !projectID.isEmpty {
            headers["x-opencode-project"] = projectID
        }
        if let requestID, !requestID.isEmpty {
            headers["x-opencode-request"] = requestID
        }
        if let parentSessionID, !parentSessionID.isEmpty {
            headers["x-opencode-parent-session-id"] = parentSessionID
            headers["x-parent-session-id"] = parentSessionID
        }
        return headers
    }

    func applying(to request: inout URLRequest) {
        for (field, value) in headers {
            request.setValue(value, forHTTPHeaderField: field)
        }
    }

    func withRequestID(_ requestID: String?) -> OpenCodeRequestContext {
        var copy = self
        copy.requestID = requestID
        return copy
    }
}
