```swift
private final class RequestRecorder: @unchecked Sendable {
    static let shared = RequestRecorder()
    private let lock = NSLock()
    private var requests: [URLRequest] = []
    func record(_ request: URLRequest) { lock.lock(); requests.append(request); lock.unlock() }
    var captured: [URLRequest] { lock.lock(); defer { lock.unlock() }; return requests }
    func reset() { lock.lock(); requests.removeAll(); lock.unlock() }
}
```

And the URLProtocol:
```swift
private final class RecordingProtocol: URLProtocol {
    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
    override func startLoading() {
        RequestRecorder.shared.record(request)
        let body: String
        if request.url?.path.hasSuffix("/models") == true {
            body = #"{"data":[{"id":"big-pickle"}]}"#
        } else {
            body = #"{"choices":[{"message":{"content":"ok"}}]}"#
        }
        let response = HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: ["Content-Type": "application/json"])!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: Data(body.utf8))
        client?.urlProtocolDidFinishLoading(self)
    }
    override func stopLoading() {}
}
```

