import Testing
import Foundation
@testable import myCoder

@Suite(
    "OpenCode Auto Free Live Model",
    .serialized,
    .enabled(if: ProcessInfo.processInfo.environment["MICODER_LIVE_TESTS"] == "1")
)
struct LiveAutoFreeModelTests {

    private struct Outcome {
        let profile: String
        let succeeded: Bool
        let detail: String
    }

    private func probe(profile: String, baseURL: URL, context: OpenCodeRequestContext) async -> Outcome {
        let client = MiCoderAutoFreeClient(session: .shared, baseURL: baseURL)
        let messages = [MiCoderAutoFreeClient.Message(role: "user", content: "Reply with the single word OK")]
        do {
            var text = ""
            for try await event in client.chatCompletion(
                model: MiCoderAutoFreeClient.defaultModelID,
                messages: messages,
                stream: false,
                context: context
            ) {
                if case .content(let chunk) = event {
                    text += chunk
                }
            }
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.isEmpty {
                return Outcome(profile: profile, succeeded: false, detail: "empty response")
            }
            return Outcome(profile: profile, succeeded: true, detail: String(trimmed.prefix(120)))
        } catch {
            return Outcome(profile: profile, succeeded: false, detail: error.localizedDescription)
        }
    }

    private func report(_ outcomes: [Outcome]) {
        for outcome in outcomes {
            let marker = outcome.succeeded ? "PASS" : "FAIL"
            print("[auto-free-live] \(marker) \(outcome.profile) — \(outcome.detail)")
        }
    }

    @Test("big-pickle answers through the production request context")
    func bigPickleThroughProductionContext() async {
        let outcome = await probe(
            profile: "production context @ \(MiCoderAutoFreeClient.providerBaseURL.absoluteString)",
            baseURL: MiCoderAutoFreeClient.providerBaseURL,
            context: .generated()
        )
        report([outcome])
        #expect(outcome.succeeded, "big-pickle failed with the production context: \(outcome.detail)")
    }

    @Test("header probe matrix finds a working big-pickle request")
    func headerProbeMatrix() async {
        let zen = MiCoderAutoFreeClient.providerBaseURL
        let inference = URL(string: "https://opencode.ai/inference/openai/v1")!

        let production = OpenCodeRequestContext.generated()
        let withRequestID = production.withRequestID(OpenCodeRequestContext.requestID())

        var cliHeaders: [String: String] = [
            "x-opencode-client": "opencode",
            "User-Agent": "opencode/stable/1.19.4/opencode"
        ]
        let cli = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: OpenCodeRequestContext.requestID(),
            additionalHeaders: cliHeaders
        )

        cliHeaders["Authorization"] = "Bearer public"
        let cliBearer = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: OpenCodeRequestContext.requestID(),
            additionalHeaders: cliHeaders
        )

        let cliDev = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: OpenCodeRequestContext.requestID(),
            additionalHeaders: [
                "x-opencode-client": "cli",
                "User-Agent": "opencode/dev/1.19.4/opencode"
            ]
        )

        let bare = OpenCodeRequestContext(
            sessionID: production.sessionID,
            additionalHeaders: [:]
        )

        let plans: [(String, URL, OpenCodeRequestContext)] = [
            ("production context", zen, production),
            ("production context + request id", zen, withRequestID),
            ("cli headers", zen, cli),
            ("cli headers + bearer public", zen, cliBearer),
            ("cli dev headers", zen, cliDev),
            ("session headers only", zen, bare),
            ("production context @ inference", inference, production),
            ("cli headers @ inference", inference, cli),
            ("cli headers + bearer public @ inference", inference, cliBearer)
        ]

        var outcomes: [Outcome] = []
        for (name, baseURL, context) in plans {
            let outcome = await probe(profile: "\(name) @ \(baseURL.absoluteString)", baseURL: baseURL, context: context)
            outcomes.append(outcome)
            if outcome.succeeded { break }
        }
        report(outcomes)
        #expect(outcomes.contains(where: { $0.succeeded }), "no header profile completed big-pickle")
    }
}

