    /// 12 hex characters derived from a descending timestamp plus 14 random
    /// base62 characters.
    private func upstreamTimestampIdentifier() -> String {
        let alphabet = Array("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")
        let timestamp = UInt64(Date().timeIntervalSince1970 * 1000)
        let current = timestamp &* 0x1000 &+ 1
        let value = ~current
        var body = ""
        for index in 0..<6 {
            let byte = (value >> UInt64(40 - 8 * index)) & 0xff
            body += String(format: "%02x", byte)
        }
        for _ in 0..<14 {
            body += alphabet[Int.random(in: 0...255) % alphabet.count]
        }
        return body
    }

    private func probe(
        profile: String,
        baseURL: URL,
        context: OpenCodeRequestContext,
        messages: [MiCoderAutoFreeClient.Message]? = nil
    ) async -> Outcome {
        let client = MiCoderAutoFreeClient(session: .shared, baseURL: baseURL)
        let payload = messages ?? [
            MiCoderAutoFreeClient.Message(role: "user", content: "Reply with the single word OK")
        ]
        do {
            var text = ""
            for try await event in client.chatCompletion(
                model: MiCoderAutoFreeClient.defaultModelID,
                messages: payload,
                stream: false,
                context: context
            ) {
                if case .content(let chunk) = event {
                    text += chunk
                }
            }
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.isEmpty {
                return Outcome(profile: profile, succeeded: false, detail: "empty response")
            }
            return Outcome(profile: profile, succeeded: true, detail: String(trimmed.prefix(120)))
        } catch {
            return Outcome(profile: profile, succeeded: false, detail: error.localizedDescription)
        }
    }

    private func report(_ outcomes: [Outcome]) {
        for outcome in outcomes {
            let marker = outcome.succeeded ? "PASS" : "FAIL"
            print("[auto-free-live] \(marker) \(outcome.profile) — \(outcome.detail)")
        }
    }

    @Test("big-pickle answers through the production request context")
    func bigPickleThroughProductionContext() async {
        let outcome = await probe(
            profile: "production context @ \(MiCoderAutoFreeClient.providerBaseURL.absoluteString)",
            baseURL: MiCoderAutoFreeClient.providerBaseURL,
            context: .generated()
        )
        report([outcome])
        #expect(outcome.succeeded, "big-pickle failed with the production context: \(outcome.detail)")
    }

    @Test("header probe matrix finds a working big-pickle request")
    func headerProbeMatrix() async {
        let zen = MiCoderAutoFreeClient.providerBaseURL
        let inference = URL(string: "https://opencode.ai/inference/openai/v1")!
        let project = OpenCodeRequestContext.projectID(fromPath: "/Users/apple/projects/micoder-987719cf")

        let production = OpenCodeRequestContext(
            sessionID: OpenCodeRequestContext.sessionID(from: "live-probe-session"),
            projectID: project,
            requestID: OpenCodeRequestContext.requestID()
        )

        let cliClient = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: production.requestID,
            additionalHeaders: ["x-opencode-client": "cli"]
        )

        let withAffinity = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: production.requestID,
            additionalHeaders: [
                "x-session-affinity": production.sessionID,
                "X-Session-Id": production.sessionID
            ]
        )

        let withPublicBearer = OpenCodeRequestContext(
            sessionID: production.sessionID,
            projectID: production.projectID,
            requestID: production.requestID,
            additionalHeaders: ["Authorization": "Bearer public"]
        )

        let withoutProject = OpenCodeRequestContext(
            sessionID: production.sessionID,
            requestID: production.requestID
        )

        let timestampIdentifiers = OpenCodeRequestContext(
            sessionID: "ses_" + upstreamTimestampIdentifier(),
            projectID: project,
            requestID: "msg_" + upstreamTimestampIdentifier()
        )

        let systemPromptMessages: [MiCoderAutoFreeClient.Message] = [
            .init(role: "system", content: "You are an AI coding assistant. You help with software engineering tasks."),
            .init(role: "user", content: "Reply with the single word OK")
        ]

        let plans: [(String, URL, OpenCodeRequestContext, [MiCoderAutoFreeClient.Message]?)] = [
            ("production context", zen, production, nil),
            ("cli client", zen, cliClient, nil),
            ("with affinity headers", zen, withAffinity, nil),
            ("with bearer public", zen, withPublicBearer, nil),
            ("without project header", zen, withoutProject, nil),
            ("upstream timestamp identifiers", zen, timestampIdentifiers, nil),
            ("production context + system prompt", zen, production, systemPromptMessages),
            ("production context @ inference", inference, production, nil),
            ("cli client @ inference", inference, cliClient, nil),
            ("with bearer public @ inference", inference, withPublicBearer, nil)
        ]

        var outcomes: [Outcome] = []
        for (name, baseURL, context, messages) in plans {
            let outcome = await probe(
                profile: "\(name) @ \(baseURL.absoluteString)",
                baseURL: baseURL,
                context: context,
                messages: messages
            )
            outcomes.append(outcome)
            if outcome.succeeded { break }
        }
        report(outcomes)
        #expect(outcomes.contains(where: { $0.succeeded }), "no header profile completed big-pickle")
    }
}

