  const headers: Record<string,string> = {}
  for (const [k, v] of Object.entries(base.headers as Record<string,string>)) {
    if (["content-length","host","connection","accept-encoding"].includes(k)) continue
    headers[k] = v
  }
  headers["x-opencode-session"] = session
  headers["x-opencode-session-id"] = session
  headers["x-opencode-request"] = request
  return headers
}
