const chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
let lastTimestamp = 0
let counter = 0
function identifier(descending = true) {
  const length = 26
  const timestamp = Date.now()
  if (timestamp !== lastTimestamp) { lastTimestamp = timestamp; counter = 0 }
  counter++
  const current = BigInt(timestamp) * 0x1000n + BigInt(counter)
  const value = descending ? ~current : current
  let time = ""
  for (let index = 0; index < 6; index++) {
    time += Number((value >> BigInt(40 - 8 * index)) & 0xffn).toString(16).padStart(2, "0")
  }
  const bytes = new Uint8Array(length - 12)
  crypto.getRandomValues(bytes)
  return time + Array.from(bytes, (b) => chars[b % 62]).join("")
}
const base = JSON.parse(await Bun.file("/tmp/opencode/oc-probe/replay.json").text())
function headersWith(session: string, request: string) {
  const headers: Record<string,string> = {}
  for (const [k, v] of Object.entries(base.headers as Record<string,string>)) {
    if (["content-length","host","connection","accept-encoding"].includes(k)) continue
    headers[k] = v
  }
  headers["x-opencode-session"] = session
  headers["x-opencode-session-id"] = session
  headers["x-opencode-request"] = request
  return headers
}
const user = { role: "user", content: "Reply with the single word OK" }
const minimal = { model: "big-pickle", messages: [user], stream: true }
let ok = 0, gated = 0, other = 0
const codes: Record<string, number> = {}
for (let i = 0; i < 12; i++) {
  const session = "ses_" + identifier()
  const request = "msg_" + identifier()
  const res = await fetch("https://opencode.ai/zen/v1/chat/completions", { method: "POST", headers: headersWith(session, request), body: JSON.stringify(minimal) })
