  const text = await res.text()
  if (res.status === 200) { ok++; console.log("OK  ", session) }
  else if (text.includes("FreeTierError")) { gated++; console.log("GATE", session) }
  else { other++; console.log("OTHER", res.status, session, text.slice(0,120)) }
}
console.log("summary", { ok, gated, other, codes })
