     static func fetchModels(for config: LocalProviderConfig) async -> [String]? {
         let endpoint: String
         switch config.kind {
         case .ollama:
             endpoint = config.serveBaseURL + "/api/tags"
         case .openCode:
             endpoint = config.serveBaseURL + "/config/providers"
         case .localAgent:
