     private struct ParameterDetailRow: View {
         let label: String
         let value: String

         var body: some View {
             HStack {
                 Text(label)
                     .interfaceFont(size: 11)
                     .foregroundColor(Color.mimo.textMuted)
                 Spacer()
                 Text(value)
                     .interfaceFont(size: 11, weight: .medium)
                     .foregroundColor(Color.mimo.textPrimary)
                     .lineLimit(1)
             }
         }
     }
 }

