                    provider.selectedModel = nextModel.id
                    provider.modelStatuses[nextModel.id] = "Active · fallback eligible"
                    provider.consecutiveFailures = 0
                    provider.statusMessage = "Switched from \(currentModel) to \(nextModel.id): \(reason)"
