import Testing
import Foundation
@testable import myCoder

@Suite(
    "OpenCode Auto Free Live Model",
    .serialized,
    .enabled(if: ProcessInfo.processInfo.environment["MICODER_LIVE_TESTS"] == "1")
)
struct LiveAutoFreeModelTests {

    private struct Outcome {
        let profile: String
        let succeeded: Bool
        let detail: String
    }

    private func probe(
        profile: String,
        baseURL: URL,
        context: OpenCodeRequestContext,
        messages: [MiCoderAutoFreeClient.Message]? = nil,
        parameters: ModelCallParameters = ModelCallParameters(),
        stream: Bool = false
    ) async -> Outcome {
        let client = MiCoderAutoFreeClient(session: .shared, baseURL: baseURL)
        let payload = messages ?? [
            MiCoderAutoFreeClient.Message(role: "user", content: "Reply with the single word OK")
        ]
        do {
            var text = ""
            for try await event in client.chatCompletion(
                model: MiCoderAutoFreeClient.defaultModelID,
                messages: payload,
                parameters: parameters,
                stream: stream,
                context: context
            ) {
                if case .content(let chunk) = event {
                    text += chunk
                }
            }
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.isEmpty {
                return Outcome(profile: profile, succeeded: false, detail: "empty response")
            }
            return Outcome(profile: profile, succeeded: true, detail: String(trimmed.prefix(120)))
        } catch {
            return Outcome(profile: profile, succeeded: false, detail: error.localizedDescription)
        }
    }

    private func report(_ outcomes: [Outcome]) {
        for outcome in outcomes {
            let marker = outcome.succeeded ? "PASS" : "FAIL"
            print("[auto-free-live] \(marker) \(outcome.profile) — \(outcome.detail)")
        }
    }

    /// Direct Zen request from myCoder's own client. The upstream free tier
    /// only serves genuine OpenCode traffic (probed live 2026-10-24), so the
    /// expected answer today is the documented free-tier gate; the request
    /// itself must reach the upstream with the official client contract.
    @Test("Direct Zen request carries the official contract and reports the upstream verdict")
    func directZenRequestVerdict() async throws {
        let context = OpenCodeRequestContext(
            sessionID: OpenCodeRequestContext.sessionID(from: "live-probe-session"),
            projectID: OpenCodeRequestContext.projectID(fromPath: "/Users/apple/projects/micoder-987719cf"),
            requestID: OpenCodeRequestContext.requestID()
        )
        #expect(context.headers["x-opencode-session-id"]?.hasPrefix("ses_") == true)
        #expect(context.headers["x-opencode-request"]?.hasPrefix("msg_") == true)
        #expect(context.headers["User-Agent"] == OpenCodeRequestContext.userAgent)

        let client = MiCoderAutoFreeClient(session: .shared)
        do {
            var text = ""
            for try await event in client.chatCompletion(
                model: MiCoderAutoFreeClient.defaultModelID,
                messages: [.init(role: "user", content: "Reply with the single word OK")],
                stream: false,
                context: context
            ) {
                if case .content(let chunk) = event {
                    text += chunk
                }
            }
            print("[auto-free-live] PASS direct Zen — \(text.prefix(120))")
        } catch let error as MiCoderAutoFreeError {
            print("[auto-free-live] BLOCKED direct Zen — \(error.localizedDescription)")
            guard case .freeTierBlocked = error else {
                Issue.record("unexpected upstream error: \(error.localizedDescription)")
                return
            }
        }
    }

    /// The supported path: myCoder talks to the user's own `opencode serve`,
    /// which performs the upstream request as the official client.
    @Test("big-pickle answers through a local opencode serve")
    func bigPickleThroughLocalOpenCode() async throws {
        let password = ProcessInfo.processInfo.environment["MICODER_OPENCODE_PASSWORD"] ?? "micoder-live"
        let authHeader = try #require(LocalProviderConfig.basicAuthHeader(username: "opencode", password: password))
        let headers = ["Authorization": authHeader]
        let baseURL = ProcessInfo.processInfo.environment["MICODER_OPENCODE_URL"] ?? "http://127.0.0.1:4096"

        let result = try await OpenCodeServeClient.send(
            baseURL: baseURL,
            headers: headers,
            modelID: MiCoderAutoFreeClient.defaultModelID,
            text: "Reply with the single word OK",
            providerID: "opencode"
        )
        print("[auto-free-live] PASS local opencode serve — \(result.content.prefix(120))")
        #expect(!result.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
    }
}

