    private static func flattenedArguments(_ json: String) -> [String: String] {
        let trimmed = json.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty,
              let data = trimmed.data(using: .utf8),
              let object = try? JSONDecoder().decode([String: ToolArgumentValue].self, from: data) else {
            return [:]
