```

And a `ToolArgumentValue` enum:
```swift
private enum ToolArgumentValue: Decodable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case array
    case object
    case null

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() { self = .null; return }
        if let value = try? container.decode(Bool.self) { self = .bool(value); return }
        if let value = try? container.decode(Double.self) { self = .number(value); return }
        if let value = try? container.decode(String.self) { self = .string(value); return }
        if (try? container.decode([ToolArgumentValue].self)) != nil { self = .array; return }
        if (try? container.decode([String: ToolArgumentValue].self)) != nil { self = .object; return }
        self = .null
    }

    var text: String {
        switch self {
        case .string(let value): return value
        case .number(let value): return value == value.rounded() && abs(value) < 1e15 ? String(Int(value)) : String(value)
        case .bool(let value): return value ? "true" : "false"
        case .array, .object: return ""
        case .null: return ""
        }
    }
}
```
