                 gitStatusMessage = output.isEmpty ? "Published to GitHub successfully!" : output
             }
             await refreshGitFromLocal()
         } catch {
             await MainActor.run {
                 isGitBusy = false
                 gitStatusMessage = "Failed to publish: \(error.localizedDescription)"
             }
