     let id = UUID()
     let info: DetectedProviderInfo
     let host: String
     let port: Int
     /// Transient basic-auth for the confirm step (never persisted as-is:
     /// username lands on the config, password goes to the Keychain).
     var username: String = ""
     var password: String = ""
 }

