    if not fp.startswith('/Users/apple/projects/micoder-987719cf'): continue
    cur = open(fp).read() if os.path.exists(fp) else None
    state = cur
    conflicts=[]
    applied=[]
    for tool,inp in items:
        if tool=='write':
            state = inp['content']
        else:
            old=inp['oldString']; new=inp['newString']
            if state is None:
                conflicts.append('missing file'); continue
            if old in state:
                state = state.replace(old,new) if inp.get('replaceAll') else state.replace(old,new,1)
                applied.append('edit')
            elif new in state:
