import json, subprocess, os, difflib
ROOT='/Users/apple/projects/micoder-987719cf'
d=json.load(open('/Users/apple/projects/opencode-api.json'))
ms=d['messages']
ops=[]
for mi,m in enumerate(ms):
    for p in m.get('parts',[]):
        if p.get('type')=='tool' and p.get('tool') in ('edit','write'):
            st=p.get('state',{}); inp=st.get('input',{}) or {}
            if st.get('status')!='completed': continue
            ops.append((m['info']['time']['created'], mi, p['tool'], inp))
ops.sort()
from collections import OrderedDict
byfile=OrderedDict()
for t,mi,tool,inp in ops:
    byfile.setdefault(inp['filePath'],[]).append((mi,tool,inp))

def head_version(rel):
    r=subprocess.run(['git','show','HEAD:'+rel],cwd=ROOT,capture_output=True,text=True)
    return r.stdout if r.returncode==0 else None

results={}
for fp,items in byfile.items():
    if not fp.startswith(ROOT): continue
    rel=os.path.relpath(fp,ROOT)
    base=head_version(rel)
    if base is None:
        base=open(fp).read() if os.path.exists(fp) else None
    state=base; ok=True; issues=[]
    for mi,tool,inp in items:
        if tool=='write':
            state=inp['content']
        else:
            old=inp['oldString']; new=inp['newString']
            if state is None: ok=False; issues.append(f'missing base {rel}'); break
            if old in state:
                state=state.replace(old,new) if inp.get('replaceAll') else state.replace(old,new,1)
            else:
                ok=False; issues.append(f'msg{mi}: oldString not found in reconstruction: {old[:60]!r}')
    cur=open(fp).read() if os.path.exists(fp) else None
    same = (state==cur)
    results[rel]=(ok, issues, state, cur)
    print(f"{'OK ' if ok else 'BAD'} {'SAME' if same else 'DIFF'} {rel}" + (f"  issues={len(issues)}" if issues else ""))
    for i in issues[:3]: print('     ', i)
json.dump({k:(v[0],v[1]) for k,v in results.items()}, open('/tmp/opencode/recon_status.json','w'))
import pickle
pickle.dump({k:(v[2],v[3]) for k,v in results.items()}, open('/tmp/opencode/recon.pkl','wb'))
PY

