  let time = ""
  for (let index = 0; index < 6; index++) {
    time += Number((value >> BigInt(40 - 8 * index)) & 0xffn).toString(16).padStart(2, "0")
  }
  const bytes = new Uint8Array(14)
  crypto.getRandomValues(bytes)
  return time + Array.from(bytes, (b) => chars[b % 62]).join("")
}
function headers() {
  const session = "ses_" + upstreamBody()
  const request = "msg_" + upstreamBody(Date.now(), false)
  return {
    ...baseHeaders,
    "x-opencode-session": session,
    "x-opencode-session-id": session,
    "x-opencode-request": request,
    "x-opencode-project": "global",
  }
}
const officialBody = official.body as any
const readTool = officialBody.tools.find((t: any) => t.function.name === "read")
const systemMessage = officialBody.messages.find((m: any) => m.role === "system")
const userMessage = officialBody.messages.find((m: any) => m.role === "user")
const variants: [string, any][] = [
  ["A control: official body as captured", JSON.parse(JSON.stringify(officialBody))],
  ["B official body without system message", { ...officialBody, messages: [userMessage] }],
