  ["D official body without stream_options", { ...officialBody, stream_options: undefined }],
  ["E official body without max_tokens", { ...officialBody, max_tokens: undefined }],
  ["F no system + only read tool + tool_choice none", { model: officialBody.model, messages: [userMessage], stream: true, tools: [readTool], tool_choice: "none" }],
  ["G no system + only read tool, no tool_choice", { model: officialBody.model, messages: [userMessage], stream: true, tools: [readTool] }],
  ["H no system + full tools + tool_choice auto", { ...officialBody, messages: [userMessage], tool_choice: "auto" }],
]
for (const [name, body] of variants) {
  const res = await fetch("https://opencode.ai/zen/v1/chat/completions", {
    method: "POST",
