const captured = JSON.parse(await Bun.file("/tmp/opencode/oc-probe/captured.json").text())
const post = captured.filter((r: any) => r.method === "POST" && r.body)
const official = post.find((r: any) => Array.isArray(r.body.tools) && r.body.tools.length > 1) ?? post[0]
const baseHeaders: Record<string, string> = {}
for (const [k, v] of Object.entries(official.headers as Record<string, string>)) {
  if (["content-length", "host", "connection", "accept-encoding"].includes(k)) continue
  baseHeaders[k] = v
}
const chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
function upstreamBody(timestamp = Date.now(), descending = true): string {
  const current = BigInt(timestamp) * 0x1000n + 1n
  const value = descending ? ~current : current
  let time = ""
  for (let index = 0; index < 6; index++) time += Number((value >> BigInt(40 - 8 * index)) & 0xffn).toString(16).padStart(2, "0")
  const bytes = new Uint8Array(14); crypto.getRandomValues(bytes)
  return time + Array.from(bytes, (b) => chars[b % 62]).join("")
}
function headers() {
  const session = "ses_" + upstreamBody(), request = "msg_" + upstreamBody(Date.now(), false)
  return { ...baseHeaders, "x-opencode-session": session, "x-opencode-session-id": session, "x-opencode-request": request, "x-opencode-project": "global" }
}
const officialBody = official.body as any
const readTool = officialBody.tools.find((t: any) => t.function.name === "read")
const systemMessage = officialBody.messages.find((m: any) => m.role === "system")
const userMessage = officialBody.messages.find((m: any) => m.role === "user")
const full = String(systemMessage.content)
const lengths = [4000, 6000, 7000, 7400, 7700, 8000, 9000, 11000]
for (const length of lengths) {
  const body = { model: officialBody.model, messages: [{ role: "system", content: full.slice(0, length) }, userMessage], stream: true, tools: [readTool] }
  const res = await fetch("https://opencode.ai/zen/v1/chat/completions", { method: "POST", headers: headers(), body: JSON.stringify(body) })
  const text = await res.text()
  const verdict = text.includes("FreeTierError") ? "GATE" : res.status === 200 ? "OK" : res.status === 429 ? "QUOTA" : String(res.status)
  console.log(String(length).padStart(6), verdict, res.status)
  await new Promise((r) => setTimeout(r, 2200))
}
