import Testing
import Foundation
@testable import myCoder

@Suite("Temp request dump", .enabled(if: ProcessInfo.processInfo.environment["MICODER_DUMP_REQUEST"] == "1"))
struct TempRequestDumpTests {
    @Test func dumpRequest() async throws {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [TempDumpProtocol.self]
        let session = URLSession(configuration: configuration)
        defer { session.invalidateAndCancel() }
        let context = OpenCodeRequestContext(
            sessionID: OpenCodeRequestContext.sessionID(from: "live-probe-session"),
            projectID: OpenCodeRequestContext.projectID(fromPath: "/Users/apple/projects/micoder-987719cf"),
            requestID: OpenCodeRequestContext.requestID()
        )
        let client = MiCoderAutoFreeClient(session: session)
        for try await _ in client.chatCompletion(
            model: MiCoderAutoFreeClient.defaultModelID,
            messages: [.init(role: "user", content: "Reply with the single word OK")],
            context: context
        ) {}
        let headers = TempDumpProtocol.lastHeaders ?? [:]
        let body = TempDumpProtocol.lastBody ?? Data()
        let payload: [String: Any] = [
            "headers": headers,
            "body": String(data: body, encoding: .utf8) ?? ""
        ]
        let data = try JSONSerialization.data(withJSONObject: payload)
        try data.write(to: URL(fileURLWithPath: "/tmp/opencode/oc-probe/swift_request.json"))
    }
}

private final class TempDumpProtocol: URLProtocol {
    private static let lock = NSLock()
    private static var headers: [String: String] = [:]
    private static var body: Data?

    static var lastHeaders: [String: String]? {
        lock.lock(); defer { lock.unlock() }
        return headers
    }

    static var lastBody: Data? {
        lock.lock(); defer { lock.unlock() }
        return body
    }

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        var capturedHeaders: [String: String] = [:]
        for (key, value) in request.allHTTPHeaderFields ?? [:] { capturedHeaders[key] = value }
        var capturedBody = Data()
        if let body = request.httpBody {
            capturedBody = body
        } else if let stream = request.httpBodyStream {
            stream.open()
            defer { stream.close() }
            let bufferSize = 4096
            var buffer = [UInt8](repeating: 0, count: bufferSize)
            while stream.hasBytesAvailable {
                let read = stream.read(&buffer, maxLength: bufferSize)
                if read <= 0 { break }
                capturedBody.append(buffer, count: read)
            }
        }
        Self.lock.lock()
        Self.headers = capturedHeaders
        Self.body = capturedBody
        Self.lock.unlock()

        let payload = "data: {\"choices\":[{\"delta\":{\"content\":\"ok\"}}]}\n\ndata: [DONE]\n\n"
        let http = HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil,
                                   headerFields: ["Content-Type": "text/event-stream"])!
        client?.urlProtocol(self, didReceive: http, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: Data(payload.utf8))
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

