     var readCount = 0
 }

 private struct AutoFreeCountingBytes: AsyncSequence, AsyncIteratorProtocol {
     typealias Element = UInt8
     let counter: AutoFreeByteReadCounter

     func makeAsyncIterator() -> Self { self }

