                let completionBody = CompletionRequest(
                    model: effectiveModel,
                    messages: MiCoderAutoFreeClient.messagesWithEnvironment(
                        messages,
                        projectRoot: projectRoot,
                        isGitRepo: isGitRepo
                    ),
