         // Session routes table
         try db.run(sessionRoutes.create(ifNotExists: true) { t in
             t.column(sessionRouteSessionId, primaryKey: true)
             t.column(sessionRouteProjectPath)
             t.column(sessionRouteUpdatedAt)
