         // Messages table
         try db.run(messages.create(ifNotExists: true) { t in
             t.column(messageId, primaryKey: true)
             t.column(messageSessionId)
             t.column(messageRole)
             t.column(messageContent)
             t.column(messageCreatedAt)
             t.column(messageModelId)
