                    }
                }
            }
            Divider()
            Button(action: { appState.agentMode = .plan }) {
                HStack {
                    Image(systemName: AgentMode.plan.icon)
                    Text(L.t(AppLocalizationKey.locSwitchPlanAgent))
                }
            }
            .disabled(!canSelectPlan)
            .overlay {
                if !canSelectPlan {
                    // `.help()` doesn't render on disabled controls — put the
