                             m.content = merged; m.isFinished = finished; m.isStreaming = streaming
                             // Keep the tool spoilers: parts survive the
                             // final answer instead of being wiped.
                             if !toolPartsBox.parts.isEmpty { m.parts = toolPartsBox.parts }
                         }
