Now let me implement task 1. Concrete changes:

**A. New file `myCoder/Sources/Services/ProjectlessWorkspaceLogic.swift`** ✓:
```swift
import Foundation

/// The "no project" mode: a chat that is not attached to a project folder.
/// It still has a real working directory (the user's home) so tools, shell
/// commands and file reads work.
enum ProjectlessWorkspaceLogic {
    static let workspaceID = ChatSession.standaloneProjectKey

    /// Working directory of a project-less chat.
    static func workingDirectory(homeDirectory: String = FileManager.default.homeDirectoryForCurrentUser.path) -> String {
        homeDirectory
    }

    /// True when the workspace is the synthetic project-less workspace.
    static func isProjectless(_ workspace: Workspace?) -> Bool {
        workspace?.id == workspaceID
    }

    /// The working directory for a chat: the project folder for a project
    /// chat, the home directory for a project-less one.
    static func workingDirectory(for workspace: Workspace?, sessionDirectory: String?, homeDirectory: String = ...) -> String
}
