     @MainActor
     func restoreLastWorkspace() {
         guard selectedWorkspace == nil else { return }
         let savedID = defaults.string(forKey: "com.mycoder.lastWorkspaceID")
         guard let workspace = WorkspaceRestoreLogic.restore(
             workspaces: workspaces,
