/// Repair a tool-call JSON body that a model emitted with structural damage:
/// raw control characters inside strings (a literal newline instead of \n)
/// and/or missing closing braces at the end. Live 2026-10-25: a model emitted
/// a 16 KB `write_file` body and forgot the final `}` of the outer object —
/// the block was valid-looking but unparseable, so the tool never ran and the
/// model kept apologizing that "the system is not executing it".
private static func repairToolCallJSON(_ text: String) -> String? {
    var out = ""
    var stack: [Character] = []
    var inString = false
    var escaped = false
    var index = text.startIndex
    while index < text.endIndex {
        let ch = text[index]
        if inString {
            if escaped {
                out.append(ch)
                escaped = false
            } else if ch == "\\" {
                out.append(ch)
                escaped = true
            } else if ch == "\"" {
                out.append(ch)
                inString = false
            } else if ch == "\n" {
                out.append("\\n")
            } else if ch == "\r" {
                out.append("\\r")
            } else if ch == "\t" {
                out.append("\\t")
            } else if ch.unicodeScalars.first.map({ $0.value < 0x20 }) == true {
                out.append(String(format: "\\u%04x", ch.unicodeScalars.first!.value))
            } else {
                out.append(ch)
            }
        } else {
            switch ch {
            case "\"": inString = true; out.append(ch)
            case "{": stack.append("}"); out.append(ch)
            case "[": stack.append("]"); out.append(ch)
            case "}", "]":
                if let expected = stack.last, expected == ch {
                    stack.removeLast()
                }
                out.append(ch)
            default: out.append(ch)
            }
        }
        index = text.index(after: index)
    }
    guard !inString, !stack.isEmpty else { return nil }
    out.append(contentsOf: stack.reversed())
    return out
}
