import Foundation
import Network

let payloadPath = CommandLine.arguments[1]
let raw = try! Data(contentsOf: URL(fileURLWithPath: payloadPath))
let parsed = try! JSONSerialization.jsonObject(with: raw) as! [String: Any]
let headers = parsed["headers"] as! [String: String]
let bodyObj = parsed["body"] as! [String: Any]
let body = try! JSONSerialization.data(withJSONObject: bodyObj)

let host = "opencode.ai"
let port: UInt16 = 443
let queue = DispatchQueue(label: "probe")
let sem = DispatchSemaphore(value: 0)

func connect(_ label: String) {
    let params = NWParameters.tcp
    let tls = NWProtocolTLS.Options()
    let sec = sec_protocol_options_create_tls_protocol_options(tls.securityProtocolOptions)
    sec_protocol_options_set_tls_server_name(sec, host)
    tls.securityProtocolOptions = sec
    params.defaultProtocolStack.applicationProtocols = [tls]
    let conn = NWConnection(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port), using: params)
    var buffer = Data()
    conn.stateUpdateHandler = { state in
        switch state {
        case .ready:
            var head = "POST /zen/v1/chat/completions HTTP/1.1\r\nHost: opencode.ai\r\n"
            for (k, v) in headers.sorted(by: { $0.key < $1.key }) {
                head += "\(k): \(v)\r\n"
            }
            head += "Content-Length: \(body.count)\r\nConnection: close\r\n\r\n"
            var out = Data(head.utf8)
            out.append(body)
            conn.send(content: out, completion: .contentProcessed { _ in })
        case .failed(let err):
            print("\(label) FAILED \(err)")
            sem.signal()
        case .cancelled:
            sem.signal()
        default:
            break
        }
    }
    conn.start(queue: queue)
    conn.receive(minimumIncompleteLength: 1, maximumLength: 65536) { data, _, isComplete, err in
        if let data { buffer.append(data) }
        if isComplete || err != nil {
            let text = String(data: buffer, encoding: .utf8) ?? ""
            let status = text.split(separator: "\n").first.map(String.init) ?? "?"
            let cfray = text.split(separator: "\n").first(where: { $0.lowercased().contains("cf-ray") }) ?? "-"
            let retry = text.split(separator: "\n").first(where: { $0.lowercased().contains("retry-after") }) ?? "-"
            print("\(label) \(status) | \(cfray) | \(retry)")
            let bodyPart = text.components(separatedBy: "\r\n\r\n").dropFirst().joined(separator: "\r\n\r\n")
            print("   body: \(bodyPart.prefix(160))")
            sem.signal()
        }
    }
}

connect(CommandLine.arguments.count > 2 ? CommandLine.arguments[2] : "nw_connection")
_ = sem.wait(timeout: .now() + 40)

