+        for ch in block {
+            if inString {
+                if escaped {
+                    escaped = false
+                } else if ch == "\\" {
+                    escaped = true
+                } else if ch == "\"" {
+                    inString = false
+                }
+            } else {
+                switch ch {
+                case "\"": inString = true
+                case "{": stack.append("}")
+                case "[": stack.append("]")
+                case "}", "]": if !stack.isEmpty { stack.removeLast() }
+                default: break
+                }
+            }
+        }
+        if inString || escaped {
+            return "its JSON string was not terminated (a quote was opened but never closed)"
+        }
+        if !stack.isEmpty {
+            let plural = stack.count == 1 ? "" : "s"
+            return "its JSON was unfinished (\(stack.count) closing bracket\(plural) missing)"
+        }
+        return "its JSON was invalid"
+    }
