private static func repairedJSONObject(_ text: String) -> String? {
    var out = ""
    var stack: [Character] = []
    var inString = false
    var escaped = false
    for ch in text {
        if inString {
            if escaped { out.append(ch); escaped = false }
            else if ch == "\\" { out.append(ch); escaped = true }
            else if ch == "\"" { out.append(ch); inString = false }
            else if ch == "\n" { out.append("\\n") }
            else if ch == "\r" { out.append("\\r") }
            else if ch == "\t" { out.append("\\t") }
            else if ch.unicodeScalars.allSatisfy({ $0.value < 0x20 }) { out.append("\\u\(String(format: "%04x", ch.unicodeScalars.first!.value))") }  // multi-scalar? control chars are single scalar
            else { out.append(ch) }
        } else {
            switch ch {
            case "\"": inString = true; out.append(ch)
            case "{": stack.append("}"); out.append(ch)
            case "[": stack.append("]"); out.append(ch)
            case "}", "]":
                if !stack.isEmpty { stack.removeLast() }
                out.append(ch)
            default: out.append(ch)
            }
        }
    }
    guard !inString, !escaped else { return nil }
    guard !stack.isEmpty else { return nil }
    out.append(contentsOf: stack.reversed())
    return out
}
```

Wait — but control-char escaping changes strings with real newlines into \n escapes. That changes the *content* the model intended... but that's exactly the intent: a raw newline in a JSON string means "\n". OK.

But hmm — careful: this repair applies to the WHOLE block text. If the block contains JSON followed by trailing text, the trailing text could contain braces → stack imbalance → append wrong closers. Only apply repair when strict parse fails, and after repair, parseSingleCall validates (needs "name" field etc.). If the repaired JSON fails to parse → nil → falls through. Safe.

Another subtlety: the closers `}` for `]`? My stack appends the expected closer, so reversed order is right. Mismatched closers (e.g. `}` closing `[`): I pop unconditionally — could produce valid-ish JSON. Acceptable for repair.

Also escaped at end (backslash dangling): return nil (unterminated string essentially).

