    var out = ""
    var stack: [Character] = []
    var inString = false
    var escaped = false
    var modified = false
    for ch in text {
        if inString {
            if escaped {
                out.append(ch)
                escaped = false
            } else if ch == "\\" {
                out.append(ch)
                escaped = true
            } else if ch == "\"" {
                out.append(ch)
                inString = false
            } else if ch == "\n" {
                out.append("\\n")
                modified = true
            } else if ch == "\r" {
                out.append("\\r")
                modified = true
            } else if ch == "\t" {
                out.append("\\t")
                modified = true
            } else if let scalar = ch.unicodeScalars.first, scalar.value < 0x20 {
                out.append("\\u\(String(format: "%04x", scalar.value))")
                modified = true
            } else {
                out.append(ch)
            }
        } else {
            switch ch {
            case "\"":
                inString = true
                out.append(ch)
            case "{":
                stack.append("}")
                out.append(ch)
            case "[":
                stack.append("]")
                out.append(ch)
            case "}", "]":
                if !stack.isEmpty { stack.removeLast() }
                out.append(ch)
            default:
                out.append(ch)
            }
        }
